param()

. build/azure-pipelines/win32/exec.ps1
$ErrorActionPreference = "Stop"

$tar = Join-Path $env:SystemRoot "System32\tar.exe"
$benchmarkRoot = ".build\node_modules_cache_benchmark"
$fileList = "$benchmarkRoot\node_modules_list.txt"
$currentArchive = ".build\node_modules_cache\cache.7z"
$tarZstdArchive = "$benchmarkRoot\node-modules.tar.zst"
$currentOutput = "$benchmarkRoot\7zip"
$tarZstdOutput = "$benchmarkRoot\tar-zstd"

if (-not (Test-Path $currentArchive)) {
	throw "Current node_modules cache archive not found: $currentArchive"
}

Remove-Item $benchmarkRoot -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force $benchmarkRoot, $currentOutput, $tarZstdOutput | Out-Null

exec { node build/azure-pipelines/common/listNodeModules.ts $fileList }
$expectedFileCount = (Get-Content $fileList).Count

& $tar --version
exec { 7z.exe i }

$tarCreateDuration = Measure-Command {
	exec { & $tar -caf $tarZstdArchive -T $fileList }
}

$tarExtractDuration = Measure-Command {
	exec { & $tar -xf $tarZstdArchive -C $tarZstdOutput }
}

$currentExtractDuration = Measure-Command {
	exec { 7z.exe x $currentArchive "-o$currentOutput" -aoa }
}

$tarZstdFileCount = (Get-ChildItem $tarZstdOutput -Recurse -File -Force).Count
$currentFileCount = (Get-ChildItem $currentOutput -Recurse -File -Force).Count
if ($tarZstdFileCount -ne $expectedFileCount -or $currentFileCount -ne $expectedFileCount) {
	throw "Extracted file count mismatch. Expected $expectedFileCount, tar.zst: $tarZstdFileCount, 7-Zip: $currentFileCount"
}

[pscustomobject]@{
	expectedFileCount = $expectedFileCount
	currentArchiveBytes = (Get-Item $currentArchive).Length
	tarZstdArchiveBytes = (Get-Item $tarZstdArchive).Length
	tarZstdCreateSeconds = [math]::Round($tarCreateDuration.TotalSeconds, 2)
	tarZstdExtractSeconds = [math]::Round($tarExtractDuration.TotalSeconds, 2)
	currentExtractSeconds = [math]::Round($currentExtractDuration.TotalSeconds, 2)
} | ConvertTo-Json

Remove-Item $benchmarkRoot -Recurse -Force
